ORB = '''<svg class="timeorb" viewBox="0 0 250 250" aria-hidden="true"><defs><radialGradient id="orb"><stop stop-color="#cc94ff"/><stop offset=".45" stop-color="#994efb"/><stop offset="1" stop-color="#5922b9"/></radialGradient><linearGradient id="edge" x2="1" y2="1"><stop stop-color="#ce94ff"/><stop offset="1" stop-color="#7132d6"/></linearGradient></defs><path d="M125 15l19 22 28-9 7 29 29 7-9 28 22 19-22 19 9 28-29 7-7 29-28-9-19 22-19-22-28 9-7-29-29-7 9-28-22-19 22-19-9-28 29-7 7-29 28 9z" transform="translate(8 13)" fill="#4a1a9e"/><path d="M125 15l19 22 28-9 7 29 29 7-9 28 22 19-22 19 9 28-29 7-7 29-28-9-19 22-19-22-28 9-7-29-29-7 9-28-22-19 22-19-9-28 29-7 7-29 28 9z" fill="url(#orb)" stroke="url(#edge)" stroke-width="4"/><circle cx="125" cy="111" r="55" fill="#392054" stroke="#d4ff52" stroke-width="3"/><path d="M125 77v34l24 17" fill="none" stroke="#d4ff52" stroke-width="7" stroke-linecap="round"/><circle cx="125" cy="111" r="5" fill="#d4ff52"/><g fill="#b8a0dd"><circle cx="125" cy="66" r="2"/><circle cx="170" cy="111" r="2"/><circle cx="125" cy="156" r="2"/><circle cx="80" cy="111" r="2"/></g></svg>'''


def decorate(name, body, demo):
    if name != 'index.html': return body
    start = demo.index('<div class="demotitle">')
    end = demo.index('<div class="demofoot">')
    settings = demo[start:end]
    newdemo = demo[:start] + '''<div class="demo-list" id="demo-list"><div class="demotitle">Your mods.</div><p class="demo-hint">One installed mod. A world of practice.</p><button class="demo-mod" id="open-timewarp"><span class="mod-icon">◷</span><span><strong>Time Warp</strong><small>v2.1 · World speed controls</small></span><span class="arrow">↗</span></button><p class="demo-hint">Click a mod. Its settings are right here.</p></div><div class="demo-settings" id="demo-settings" hidden><button class="demo-back" id="back-to-mods">← Back to mods</button>''' + settings + '</div>' + demo[end:]
    newdemo = newdemo.replace('Find your timing.', 'Time Warp').replace('● Native controls','● In-game menus')
    newdemo = newdemo.replace('One installed mod. A world of practice.', 'Example: Time Warp, downloaded separately.')
    stage = '<div class="playstage">' + ORB + '<span class="sticker">F10 → YOUR MODS</span><span class="spark" aria-hidden="true">✳</span>' + newdemo + '<span class="micro">A clickable preview. Your real settings live in game.</span></div>'
    return body.replace(demo, stage)

SCRIPT = '''const open=document.querySelector('#open-timewarp');const back=document.querySelector('#back-to-mods');if(open&&back){const list=document.querySelector('#demo-list');const settings=document.querySelector('#demo-settings');open.addEventListener('click',()=>{list.hidden=true;settings.hidden=false;back.focus();});back.addEventListener('click',()=>{settings.hidden=true;list.hidden=false;open.focus();});}const copyPrompt=document.querySelector('#copy-prompt');if(copyPrompt){copyPrompt.addEventListener('click',async()=>{const status=document.querySelector('#copy-status');try{await navigator.clipboard.writeText(document.querySelector('#ai-prompt').textContent);status.textContent='Prompt copied.';}catch{status.textContent='Use Download prompt or select the text below.';}});}'''
